    def put(r,c):
        if out[r][c]==0: out[r][c]=3
    if A[0]==B[0]:
        for c in range(min(A[1],B[1]),max(A[1],B[1])+1): put(A[0],c)
        for k,(r,c) in enumerate(P):
            if k==a or k==b: continue
            step=1 if r>A[0] else -1
            rr=A[0]+step
            while 0<=rr<H and rr!=r:
                put(rr,c); rr+=step
    elif A[1]==B[1]:
        for r in range(min(A[0],B[0]),max(A[0],B[0])+1): put(r,A[1])
        for k,(r,c) in enumerate(P):
            if k==a or k==b: continue
            step=1 if c>A[1] else -1
            cc=A[1]+step
            while 0<=cc<W and cc!=c:
                put(r,cc); cc+=step
    return out
